import os
import requests
from zipfile import ZipFile, BadZipFile
def task_func(url, download_path="mnt/data/downloads/"):
    if not isinstance(url, str) or not url:
        return "Error: Invalid URL provided."

    if not os.path.exists(download_path):
        os.makedirs(download_path)

    try:
        response = requests.get(url, stream=True, timeout=10, verify=False)
        response.raise_for_status()
        if 'application/zip' not in response.headers.get('Content-Type', ''):
            return "Error: The URL does not point to a ZIP file."

        zip_file_path = os.path.join(download_path, "downloaded_file.zip")
        with open(zip_file_path, 'wb') as f:
            for chunk in response.iter_content(chunk_size=8192):
                f.write(chunk)
    except requests.RequestException:
        return "Error: Unable to download the file from the provided URL."

    try:
        with ZipFile(zip_file_path, 'r') as zip_ref:
            zip_ref.extractall(download_path)
    except BadZipFile:
        return "Error: The downloaded file is not a valid ZIP file."
    except Exception as e:
        return f"Error: {e}"

    return download_path

import requests
from pathlib import Path
import zipfile
DOWNLOAD_DIR = Path("downloads")
ZIP_DIR = Path("unzipped_files")
def task_func(url, filename):
    if not isinstance(url, str) or not url or not isinstance(filename, str) or not filename:
        return ("Error: Invalid URL or filename provided.", [])

    DOWNLOAD_DIR.mkdir(exist_ok=True)
    ZIP_DIR.mkdir(exist_ok=True)

    zip_path = DOWNLOAD_DIR / filename
    try:
        response = requests.get(url, stream=True, timeout=10, verify=False)
        response.raise_for_status()
        with open(zip_path, 'wb') as f:
            for chunk in response.iter_content(chunk_size=8192):
                f.write(chunk)
    except requests.RequestException as e:
        return (f"Error: Failed to download the file: {e}", [])

    try:
        with zipfile.ZipFile(zip_path, 'r') as zip_ref:
            zip_ref.extractall(ZIP_DIR)
            filenames = zip_ref.namelist()
    except zipfile.BadZipFile as e:
        return (f"Error: Failed to extract the zip file: {e}", [])

    return ("Success", filenames)

