import requests
def task_func(user, API_URL = 'https://api.github.com/users/'):
    if not user or not isinstance(user, str):
        raise ValueError("Invalid GitHub username provided.")

    url = f"{API_URL}{user}/repos"
    try:
        response = requests.get(url, verify=False)
        response.raise_for_status()
    except requests.RequestException as e:
        raise ConnectionError(f"Failed to connect to GitHub API: {e}")

    try:
        repos = response.json()
        if not isinstance(repos, list):
            raise ValueError("Invalid response format from GitHub API.")
        sorted_repos = sorted(repos, key=lambda repo: repo['created_at'])
        return [repo['name'] for repo in sorted_repos]
    except (KeyError, json.JSONDecodeError) as e:
        raise ValueError(f"Error parsing GitHub API response: {e}")

