import unicodedata
import requests
URL = 'https://api.github.com/users/'
def task_func(username):
    if not username or not isinstance(username, str):
        raise ValueError("Username must be a non-empty string.")

    try:
        response = requests.get(f"{URL}{username}", timeout=10, verify=False)
        response.raise_for_status()
        user_data = response.json()
    except requests.exceptions.RequestException as e:
        raise requests.exceptions.HTTPError(f"Error retrieving user data: {e}") from e

    normalized_data = {}
    for key, value in user_data.items():
        if isinstance(value, str):
            normalized_data[key] = unicodedata.normalize('NFKD', value).encode('ascii', 'ignore').decode('ascii')
        else:
            normalized_data[key] = value

    return normalized_data

from flask import Flask
from flask_restful import Resource, Api
import requests
def task_func(api_url, template_folder):
    if not isinstance(api_url, str) or not api_url:
        raise ValueError("Invalid API URL provided.")
    if not isinstance(template_folder, str) or not template_folder:
        raise ValueError("Invalid template folder provided.")

    app = Flask(__name__, template_folder=template_folder)
    api = Api(app)

    class ExternalAPIResource(Resource):
        def get(self):
            try:
                response = requests.get(api_url, timeout=10, verify=False)
                response.raise_for_status()
                return response.json()
            except requests.RequestException as e:
                return {"error": str(e)}, 500

    api.add_resource(ExternalAPIResource, '/api/data')

    return app

import requests
import json
import pandas as pd
import seaborn as sns
HEADERS = {
    'accept': 'application/json'
}
def task_func(url, parameters):
    if not isinstance(url, str) or not url or not isinstance(parameters, dict):
        raise Exception("Invalid URL or parameters provided.")

    try:
        response = requests.get(url, params=parameters, headers=HEADERS, verify=False)
        response.raise_for_status()
        data = response.json()
        if not data:
            raise Exception("Empty data received from the API.")
        df = pd.DataFrame(data)
        if df.empty or df.select_dtypes(include=['number']).empty:
            raise Exception("Invalid or non-numerical data received.")
    except Exception as e:
        raise Exception(f"Error accessing or processing the API data: {e}")

    correlation_matrix = df.corr()
    ax = sns.heatmap(correlation_matrix, annot=True, cmap="coolwarm")
    return df, ax
